import json

with open('/root/autodl-tmp/LIBERO-plus/libero/libero/benchmark/task_classification.json') as f:
    data = json.load(f)

for suite, tasks in data.items():
    print(f'\n=== {suite} ({len(tasks)} tasks) ===')
    categories = {}
    difficulties = {}
    for t in tasks:
        cat = t['category']
        diff = t.get('difficulty_level') or 'None'
        categories[cat] = categories.get(cat, 0) + 1
        difficulties[diff] = difficulties.get(diff, 0) + 1
    print('Categories:')
    for c, n in sorted(categories.items()):
        print(f'  {c}: {n}')
    print('Difficulties:')
    for d, n in sorted(difficulties.items(), key=lambda x: str(x[0])):
        print(f'  L{d}: {n}')
